// ChatServiceServer is the server API for ChatService service.
// All implementations must embed UnimplementedChatServiceServer
// for forward compatibility.
//
// ChatService provides channel, message, thread, reaction, and category management.
type ChatServiceServer interface {
	// Channel CRUD
	CreateChannel(context.Context, *CreateChannelRequest) (*CreateChannelResponse, error)
	GetChannel(context.Context, *GetChannelRequest) (*GetChannelResponse, error)
	UpdateChannel(context.Context, *UpdateChannelRequest) (*UpdateChannelResponse, error)
	ArchiveChannel(context.Context, *ArchiveChannelRequest) (*ArchiveChannelResponse, error)
	UnarchiveChannel(context.Context, *UnarchiveChannelRequest) (*UnarchiveChannelResponse, error)
	DeleteChannel(context.Context, *DeleteChannelRequest) (*DeleteChannelResponse, error)
	ListChannels(context.Context, *ListChannelsRequest) (*ListChannelsResponse, error)
	// Membership
	JoinChannel(context.Context, *JoinChannelRequest) (*JoinChannelResponse, error)
	LeaveChannel(context.Context, *LeaveChannelRequest) (*LeaveChannelResponse, error)
	AddMembers(context.Context, *AddMembersRequest) (*AddMembersResponse, error)
	RemoveMembers(context.Context, *RemoveMembersRequest) (*RemoveMembersResponse, error)
	GetMembers(context.Context, *GetMembersRequest) (*GetMembersResponse, error)
	UpdateChannelMember(context.Context, *UpdateChannelMemberRequest) (*UpdateChannelMemberResponse, error)
	UpdateMemberRole(context.Context, *UpdateMemberRoleRequest) (*UpdateMemberRoleResponse, error)
	// Messages
	SendMessage(context.Context, *SendMessageRequest) (*SendMessageResponse, error)
	GetMessages(context.Context, *GetMessagesRequest) (*GetMessagesResponse, error)
	GetMessage(context.Context, *GetMessageRequest) (*GetMessageResponse, error)
	UpdateMessage(context.Context, *UpdateMessageRequest) (*UpdateMessageResponse, error)
	// Prior contents of an edited message. The sender always may read them;
	// other viewers are gated by ChatPolicy.edit_history_visible_to.
	GetMessageRevisions(context.Context, *GetMessageRevisionsRequest) (*GetMessageRevisionsResponse, error)
	DeleteMessage(context.Context, *DeleteMessageRequest) (*DeleteMessageResponse, error)
	PinMessage(context.Context, *PinMessageRequest) (*PinMessageResponse, error)
	UnpinMessage(context.Context, *UnpinMessageRequest) (*UnpinMessageResponse, error)
	GetPinnedMessages(context.Context, *GetPinnedMessagesRequest) (*GetPinnedMessagesResponse, error)
	// Threads
	GetThread(context.Context, *GetThreadRequest) (*GetThreadResponse, error)
	GetThreadMessages(context.Context, *GetThreadMessagesRequest) (*GetThreadMessagesResponse, error)
	GetThreadsInbox(context.Context, *GetThreadsInboxRequest) (*GetThreadsInboxResponse, error)
	FollowThread(context.Context, *FollowThreadRequest) (*FollowThreadResponse, error)
	UnfollowThread(context.Context, *UnfollowThreadRequest) (*UnfollowThreadResponse, error)
	// Reactions
	AddReaction(context.Context, *AddReactionRequest) (*AddReactionResponse, error)
	RemoveReaction(context.Context, *RemoveReactionRequest) (*RemoveReactionResponse, error)
	// Typing and read state
	SetTyping(context.Context, *SetTypingRequest) (*SetTypingResponse, error)
	MarkChannelRead(context.Context, *MarkChannelReadRequest) (*MarkChannelReadResponse, error)
	MarkChannelUnread(context.Context, *MarkChannelUnreadRequest) (*MarkChannelUnreadResponse, error)
	MarkThreadRead(context.Context, *MarkThreadReadRequest) (*MarkThreadReadResponse, error)
	GetUnreadCounts(context.Context, *GetUnreadCountsRequest) (*GetUnreadCountsResponse, error)
	// Drafts - per-user unsent composer text, synced across devices.
	SaveDraft(context.Context, *SaveDraftRequest) (*SaveDraftResponse, error)
	DeleteDraft(context.Context, *DeleteDraftRequest) (*DeleteDraftResponse, error)
	ListDrafts(context.Context, *ListDraftsRequest) (*ListDraftsResponse, error)
	// Channel resources
	GetChannelResources(context.Context, *GetChannelResourcesRequest) (*GetChannelResourcesResponse, error)
	// Convert a group DM into a PRIVATE channel (owner only); members and
	// history carry over. Group DMs are capped, channels are not.
	ConvertGroupDmToChannel(context.Context, *ConvertGroupDmToChannelRequest) (*ConvertGroupDmToChannelResponse, error)
	// Named agent chats - multiple chats per (user, agent) pair, each renamable.
	CreateAgentChat(context.Context, *CreateAgentChatRequest) (*CreateAgentChatResponse, error)
	RenameAgentChat(context.Context, *RenameAgentChatRequest) (*RenameAgentChatResponse, error)
	ListAgentChats(context.Context, *ListAgentChatsRequest) (*ListAgentChatsResponse, error)
	// Categories
	CreateCategory(context.Context, *CreateCategoryRequest) (*CreateCategoryResponse, error)
	UpdateCategory(context.Context, *UpdateCategoryRequest) (*UpdateCategoryResponse, error)
	DeleteCategory(context.Context, *DeleteCategoryRequest) (*DeleteCategoryResponse, error)
	ListCategories(context.Context, *ListCategoriesRequest) (*ListCategoriesResponse, error)
	ReorderCategories(context.Context, *ReorderCategoriesRequest) (*ReorderCategoriesResponse, error)
	MoveChannelToCategory(context.Context, *MoveChannelToCategoryRequest) (*MoveChannelToCategoryResponse, error)
	// Agent chat folders - per-user sidebar grouping for agent DM chats.
	// Unlike categories (org-wide, admin-managed), folders are private to the
	// requesting user and only apply to their is_agent_dm channels.
	CreateAgentFolder(context.Context, *CreateAgentFolderRequest) (*CreateAgentFolderResponse, error)
	RenameAgentFolder(context.Context, *RenameAgentFolderRequest) (*RenameAgentFolderResponse, error)
	DeleteAgentFolder(context.Context, *DeleteAgentFolderRequest) (*DeleteAgentFolderResponse, error)
	ListAgentFolders(context.Context, *ListAgentFoldersRequest) (*ListAgentFoldersResponse, error)
	SetAgentChatFolder(context.Context, *SetAgentChatFolderRequest) (*SetAgentChatFolderResponse, error)
	// Respond to a destructive-tool confirmation request raised by an agent
	// running inside a chat channel. The chat layer is the front door; it
	// forwards the decision to the agents runtime via the bridge.
	RespondToAgentConfirmation(context.Context, *RespondToAgentConfirmationRequest) (*RespondToAgentConfirmationResponse, error)
	// List pending agent destructive-tool approvals still open for a channel.
	// Used on channel mount so synthetic confirmation cards survive page reloads
	// (the approval state itself lives in Valkey up to its TTL).
	GetChannelPendingApprovals(context.Context, *GetChannelPendingApprovalsRequest) (*GetChannelPendingApprovalsResponse, error)
	// Per-(channel, agent) context window stats. Drives the chat header meter
	// and group-channel per-agent popover. Mirrors `agents.v1.SessionsService.
	// GetSessionContextStats` but is keyed on the channel/agent binding.
	GetChannelAgentContextStats(context.Context, *GetChannelAgentContextStatsRequest) (*GetChannelAgentContextStatsResponse, error)
	// Batched variant of `GetChannelAgentContextStats`. Returns per-(channel,
	// agent) stats for N agents in one round-trip. Drives the group-channel
	// ChannelAgentsPopover (one row per agent member) so the popover does not
	// fan out N parallel single-agent fetches. Agents the caller can't see or
	// that are not bound to the channel are simply absent from the response
	// map (not an error).
	GetChannelAgentContextStatsBatch(context.Context, *GetChannelAgentContextStatsBatchRequest) (*GetChannelAgentContextStatsBatchResponse, error)
	// Force compaction for one (channel, agent) pair. Writes a chat message
	// with metadata.kind="summary" and bumps the binding's compaction pointer
	// so subsequent prompts roll the older history into the summary row.
	CompactChannelAgentContext(context.Context, *CompactChannelAgentContextRequest) (*CompactChannelAgentContextResponse, error)
	// Reset one agent's view of the channel. Writes a metadata.kind=
	// "context_reset" divider message AND sets binding.manual_reset_at = now()
	// so `load_context_messages` excludes everything older for this agent.
	// Per-agent: resetting agent A in a multi-agent channel does not affect
	// agent B's view.
	ResetChannelAgentContext(context.Context, *ResetChannelAgentContextRequest) (*ResetChannelAgentContextResponse, error)
	// Per-(channel, agent) model + parameter overrides stored on the binding
	// row. Empty strings mean "no override" - the agent's own configuration
	// applies.
	GetChannelAgentConfig(context.Context, *GetChannelAgentConfigRequest) (*GetChannelAgentConfigResponse, error)
	// Update the binding's overrides. Absent optional fields leave the value
	// unchanged; present-but-empty clears it (mirrors agents.v1.UpdateSession).
	UpdateChannelAgentConfig(context.Context, *UpdateChannelAgentConfigRequest) (*UpdateChannelAgentConfigResponse, error)
	// Stop an in-flight agent run in a channel. Cancels the active run for the
	// given agent - whether it is mid tool call, image generation, or text
	// generation - via the run-state cancel flag the egress task observes.
	StopAgentRun(context.Context, *StopAgentRunRequest) (*StopAgentRunResponse, error)
	// Org-level chat policy. Every member may read it (the composer gates the
	// broadcast typeahead and confirm dialog on it); updates are org-admin only.
	GetChatPolicy(context.Context, *GetChatPolicyRequest) (*GetChatPolicyResponse, error)
	UpdateChatPolicy(context.Context, *UpdateChatPolicyRequest) (*UpdateChatPolicyResponse, error)
	ForwardMessage(context.Context, *ForwardMessageRequest) (*ForwardMessageResponse, error)
	mustEmbedUnimplementedChatServiceServer()
}

